/* ============================================================
   ECHO X ORBIT vault · the model: sweep, reaction, reclaim (ExO)
   Source: the ExO playbook and indicator. No results (win rates, outcome mixes, profit factors, trade counts) are taught here:
   the rule settings the trade runs on are.
============================================================ */
(()=>{
const SIDEW=e=>e.side==='long'?'low':'high',DIR=e=>e.side==='long'?'LONG':'SHORT';
/* the walkthrough steps, shared by the chart modules */
const stepsOf=(e,which)=>{const L=e.side==='long',C=e.C,T=i=>hhmm(e.t0+i),v=(a,b)=>({from:Math.max(-1,a),count:Math.max(50,Math.min(90,b-a+8))}),al=exAlign(e);
  const all={
   level:{upto:e.runI,focus:e.runI,...v(0,e.sweepI+8),ov:[exLvl(e)],cap:`<b>A level.</b> Price is drifting toward the ${e.levelKind==='15m'?'previous 15-minute':e.levelKind==='1H'?'previous 1-hour':'previous-day'} ${SIDEW(e)} at <b>${fm(e.level)}</b>: stops and pending orders sit just beyond it. You mark it and do <b>nothing</b>. Never enter because price is near a level.`},
   run:{upto:e.sweepI-1,focus:e.sweepI-1,...v(0,e.sweepI+8),ov:[exLvl(e),boxOf(C,e.runI,e.sweepI-1,COL.ice,1),hlAt(e.R0,'start of the run',COL.gold,e.runI,{scale:true,dash:true})],cap:`<b>The delivery run.</b> A run of same-direction candles pushes price into the level. Where the run <b>started</b> (${fm(e.R0)}) matters later: a close back through it will be the signal.`},
   sweep:{upto:e.sweepI,focus:e.sweepI,...v(0,e.sweepI+8),ov:[exLvl(e),exCisd(e),exWatch(e)],cap:`<b>The sweep.</b> At <b>${T(e.sweepI)}</b> a candle trades ${L?'below':'above'} the level by ${fm(Math.abs(e.swLow-e.level),1)} points. A grey <b>WATCHING</b> tab appears on its wick and counts the candles that follow. The dotted line is the CISD line: the price a candle has to <b>close</b> through to confirm. You do nothing yet.`},
   confirm:{upto:e.confI,focus:e.confI,...v(0,e.confI+8),ov:[exLvl(e),exCisd(e),boxOf(C,e.confI,e.confI,COL.sig,.5),tagAt(e.confI,C[e.confI].c,'confirmation',L?'above':'below',COL.sig)],cap:`<b>The reaction is confirmed.</b> At <b>${T(e.confI)}</b> a candle <b>closes</b> ${L?'above':'below'} the CISD line (${fm(e.R0)}) and back inside the swept level. It took ${e.confI-e.sweepI} candle${e.confI-e.sweepI===1?'':'s'} from the sweep${e.fast?': a fast reaction':': a slow turn'}. A wick through the line would do nothing.`},
   align:{upto:e.confI,focus:e.sweepI,...v(0,e.confI+8),ov:[exLvl(e),exCisd(e),...(al?[al]:[])],cap:al?`<b>Alignment.</b> Looking left on the 15-minute and 1-hour charts, the sweep extreme (${fm(e.swLow)}) sits inside ${e.align.kind==='gap'?'an unfilled gap':'the wick zone of a rejection block'} of the right side: price was delivered into an area where the other side was already waiting.`:`<b>Alignment.</b> The sweep extreme (${fm(e.swLow)}) is not inside any 15-minute or 1-hour gap or rejection block. Aligned with nothing: skip unless there is a very specific reason.`},
   entry:{upto:e.entryI,focus:e.entryI,...v(e.sweepI-14,e.entryI+28),ov:[exLvl(e),exEntryTab(e),...exTrade(e,e.entryI+3)],cap:`<b>The entry.</b> The tab appears at the open of the candle after the confirmation: <b>ExO · ${DIR(e)} ${fm(e.E)} · 3/3</b>. The <b>stop</b> is one point beyond the sweep extreme: <b>${fm(e.stop)}</b> (${fm(e.R,1)} points). The <b>target</b> is half the swept range beyond its far end: <b>${fm(e.tgt)}</b>. The grey dotted line is the break-even step, a quarter of the way to your risk (+0.25R): <b>${fm(e.be)}</b>.`},
   result:{upto:e.exitI,focus:e.exitI,...v(e.sweepI-14,e.exitI+8),ov:[exLvl(e),exEntryTab(e),...exTrade(e,e.exitI)],cap:e.out==='target'?`<b>The target.</b> Price reaches the target at ${T(e.exitI)}. The trade ends there. You do not move the target further out.`:e.out==='scratch'?`<b>A scratch.</b> Price reached the break-even step, so the stop moved to the entry. Then it came back and stopped the trade at the entry at ${T(e.exitI)}: about the cost of the trade. That is the plan working, and it is not counted as a win.`:`<b>A full stop.</b> Price came back through the stop at ${T(e.exitI)}. A normal loss at the planned risk: log it, check which check or alignment was missing, and do not re-enter the same level in the same hour block.`}};
  return which.map(k=>all[k])};
const chartMod=(c)=>MODS.push({chart:true,...c,exam:c.exam||{bank:4,gen:c.drills.slice(0,5).map((_,i)=>[i,i<2?2:1])}});
/* ---------- x01 · the idea ---------- */
chartMod({id:'x01',o:1,ph:0,t:'The Idea: Sweep, Reaction, Reclaim',out:'Explain what ECHO X ORBIT marks, and the one-sentence version of the trade.',
 ls:['What ECHO X ORBIT is','The one-sentence trade','Sweep, reaction, reclaim','What you do and what the tool does','Strict and Discretionary','Where it runs'],
 task:'On a 1-minute chart of MNQ1! in replay, find one place where price took out an obvious high or low, then reversed. Write the sentence: a level got swept, a candle closed back through the start of the push, and where you would have entered.',
 ex:()=>exoScn(rr(901),{side:'long',fast:true,out:'target',align:'gap'}),
 learn:[
  {t:'What ECHO X ORBIT is',h:`<p>Price often pokes past an obvious level to grab the orders sitting there, then reverses. <b>ECHO X ORBIT</b> (the ExO indicator) finds that moment on the 1-minute chart. It waits for <b>proof that the move has turned</b>, then gives you an entry, a stop, a target and a break-even step, and manages the trade the same way every time.</p><p>It does not predict the day. It marks a <b>repeatable situation</b> and removes the guesswork about where to get in, where you are wrong, and where to take profit.</p>`},
  {t:'The one-sentence trade',h:key('<p>A level gets <b>swept</b>, price <b>closes back through the start of the push</b> that swept it, you <b>enter the next candle</b>, your stop sits <b>one point past the sweep</b>, and the stop goes to <b>break-even</b> once the trade is a quarter of the way to its risk.</p>','Learn this sentence')},
  {t:'Sweep, reaction, reclaim',h:tblx(['Word','What it means'],[['Sweep','A candle trades beyond a level by at least one tick'],['Reaction','Price turns, and a candle closes back through the start of the run that pushed into the level'],['Reclaim','The confirming candle closes back on the original side of the swept level, with its body and not just a wick']])},
  {t:'What you do and what the tool does',h:tblx(['The tool','You'],[['Marks the level sweep (WATCHING tab)','Wait. Most of the time nothing is happening, and that is correct'],['Draws the entry, stop, target and break-even lines','Decide whether this setup is worth taking'],['Alerts you to move the stop','Place the orders and move the stop yourself']])+`<p>ECHO X ORBIT is a <b>discretionary</b> tool, not a money machine. The point of your judgement is selection: which setups to take and which to skip. Once you are in, the plan runs itself.</p>`},
  {t:'Strict and Discretionary',h:tblx(['Mode','What it does'],[['Strict','Only setups that pass every check; one trade per hour block'],['Discretionary','Every confirmed setup is drawn with its checklist and you decide']])},
  {t:'Where it runs',h:`<p>The <b>1-minute chart</b> of NQ1! or MNQ1!, in New York time whatever your chart shows. By default it looks for trades from <b>9 to 11</b> (the 9 am and 10 am hour blocks). Other hours show setups too, but they are outside the default window, so read them as your own call.</p>`}],
 recall:rc('Break of Structure','What decides whether price "broke" a level?',['A candle close beyond it','A wick beyond it','A touch of the level','A news release'],'The close decides, not the wick. ECHO X ORBIT uses the same rule for confirmation.'),
 see:e=>stepsOf(e,['level','run','sweep','confirm','entry','result']),
 sum:e=>({ov:[exLvl(e),exCisd(e)]}),
 drills:[exTapSweep,exCisdLine,exTapConfirm,exCount,exChecks],
 bank:[
  mcq('Idea','What does ECHO X ORBIT wait for before it marks a trade?',['Proof that the move has turned','A news release','The market open','Three green candles'],'It waits for the reversal to be confirmed, never entering on the sweep itself.'),
  mcq('Idea','Does ECHO X ORBIT predict the day?',['No: it marks a repeatable situation','Yes, every morning','Only on Fridays','Only at the open'],'It removes guesswork about where to get in, where you are wrong, and where to take profit.'),
  mcq('Idea','Which sentence is the trade?',['A level is swept, price closes back through the start of the push, you enter the next candle','A level is touched and you enter at once','Price breaks a level and you chase it','A news candle prints and you fade it'],'Sweep, then confirmation, then the next open.'),
  mcq('Idea','Where does the stop go?',['One point past the sweep','Past the previous day high','At the entry','Wherever feels comfortable'],'One point beyond the sweep extreme.'),
  mcq('Idea','When does the stop move to break-even?',['When the trade is a quarter of the way to its risk (+0.25R)','At the target','Never','After 120 minutes'],'At +0.25R the stop line turns orange and an alert fires.'),
  mcq('Idea','Which mode takes only setups that pass every check?',['Strict','Discretionary','Neither','Both'],'Strict: one trade per hour block, 3/3 only.'),
  mcq('Idea','Which chart does ECHO X ORBIT run on?',['The 1-minute chart','The 15-minute chart','The daily chart','The 4-hour chart'],'1-minute, New York time.'),
  mcq('Idea','What is "reclaim"?',['The confirming candle closes back on the original side of the swept level with its body','A wick back through the level','A gap fill','A new high'],'A body close, not just a wick.'),
  mcq('Idea','Who moves your stop to break-even?',['You: the indicator alerts you','The indicator, at your broker','Your broker','Nobody'],'ECHO X ORBIT is an indicator, not a bot.'),
  mcq('Idea','What does a WATCHING tab mean?',['A level was just swept: do nothing yet','Enter now','The trade is over','The stop was hit'],'Wait for a candle to close through the CISD line.')],
 examDesc:'The idea, the one-sentence trade, and finding the sweep and the confirmation on a chart.'});
/* ---------- x02 · levels and the sweep ---------- */
chartMod({id:'x02',o:2,ph:0,t:'Levels and the Sweep',out:'Name the five levels, spot a sweep, and read the WATCHING tab.',
 ls:['The five levels','What counts as a sweep','Stacked levels and used levels','The WATCHING tab','The 30-candle watch','Never enter at the sweep'],
 task:'On a 1-minute chart in replay, mark the five levels before 9:00: the previous 15-minute and 1-hour highs and lows, the previous-day high and low, the session high and low so far, and the high and low of the hour before the block. Find the first one that gets swept.',
 ex:()=>exoScn(rr(902),{side:'short',fast:false,out:'scratch',align:'rb',level:'1H'}),
 learn:[
  {t:'The five levels',h:tblx(['Level','What it is'],[['Previous 15-minute high / low','The extremes of the last completed 15-minute candle'],['Previous 1-hour high / low','The extremes of the last completed hour'],['Previous-day high / low','Yesterday\'s extremes'],['Session high / low so far','The extremes of the session so far'],['The hour before the block','The high and low of the hour before the trading block starts']])+`<p>Stops and pending orders cluster just beyond each of them. Faint dotted lines on the chart mark them.</p>`},
  {t:'What counts as a sweep',h:`<p>A candle trades <b>beyond a level by at least one tick</b>. A swept <b>high</b> sets up a <b>short</b>; a swept <b>low</b> sets up a <b>long</b>. A sweep alone is not an entry. It is only the start of the story.</p>`},
  {t:'Stacked levels and used levels',h:`<ul><li><b>Stacked levels</b> (for example the 1-hour high and the previous-day high close together): the indicator uses the highest swept level for a high. Stacks are better than a single 15-minute level.</li><li><b>A level already swept</b> earlier in the same hour block does not trigger again unless a new level is swept. Look for the next untouched level.</li><li><b>A big news candle</b> that spikes through several levels at once is one watch and one setup. The reversal usually needs more candles.</li></ul>`},
  {t:'The WATCHING tab',h:`<p>When a level is swept, a grey <b>WATCHING</b> tab appears on the wick of the sweep. It <b>counts</b> the candles that follow: 1/3, 2/3, 3/3. After that it turns grey and reads <b>slow</b>. If the candle keeps pushing, the extreme updates and the stop will move with it.</p>`},
  {t:'The 30-candle watch',h:`<p>Within <b>30 candles</b> of the sweep, a candle has to confirm. If 30 candles pass with no confirmation, the watch <b>expires</b> and nothing is traded. Wait for a new sweep.</p>`},
  {t:'Never enter at the sweep',h:warn('<p>Entering on the sweep, before any reversal proof, or because price is "near the level", is the classic mistake. The whole point of ECHO X ORBIT is to wait for the proof. A WATCHING tab means <b>do nothing yet</b>.</p>')}],
 recall:rc('The Idea: Sweep, Reaction, Reclaim','What does a WATCHING tab mean?',['A level was just swept: do nothing yet','Enter now','The trade is over','The stop was hit'],'Wait for a candle to close through the CISD line.'),
 see:e=>stepsOf(e,['level','run','sweep']),
 sum:e=>({ov:[exLvl(e),exWatch(e)]}),
 drills:[exTapSweep,exChecks,exCount,exCisdLine],
 bank:[
  mcq('Levels','Which is one of the five levels?',['The previous 1-hour high','The weekly open','A round number','The 200 moving average'],'The five: previous 15m, previous 1H, previous day, session so far, and the hour before the block.'),
  mcq('Levels','How far past a level must a candle trade to count as a sweep?',['At least one tick','10 points','A full candle','It must close beyond it'],'One tick is enough. The close is for the confirmation, not the sweep.'),
  mcq('Levels','A swept high sets up…',['A short','A long','Nothing','A news trade'],'A swept high sets up a short; a swept low a long.'),
  mcq('Levels','Is a sweep an entry?',['No: it is only the start of the story','Yes','Only on the 1-hour','Only in Strict mode'],'You wait for the reversal proof.'),
  mcq('Levels','A level was already swept earlier in the same hour block. What happens?',['It does not trigger again unless a new level is swept','It triggers again','The hour block is cancelled','The stop doubles'],'Look for the next untouched level.'),
  mcq('Levels','Two levels sit close together (the 1-hour high and the previous-day high). How are they treated?',['As one stack: the highest swept level is used','The lower one only','Neither','As two trades'],'Stacked levels are better than a single 15-minute level.'),
  mcq('Levels','What does the WATCHING tab count?',['The candles since the sweep: 1/3, 2/3, 3/3','The dollars at risk','The levels swept today','The minutes in the trade'],'After 3 it turns grey and reads slow.'),
  mcq('Levels','How long does a watch last without a confirmation?',['30 candles','3 candles','All day','Until the next hour'],'Then it expires and nothing is traded.'),
  mcq('Levels','A big news candle spikes through several levels at once. What do you expect?',['One watching tab, one setup, and the reversal usually needs more candles','Several setups at once','No setup ever','An instant entry'],'Consider standing aside for a few minutes after the release: your call.'),
  mcq('Levels','Price is drifting toward a level and you have no setup. What do you do?',['Mark the level and do nothing','Enter early','Place a limit at the level','Double up'],'Never enter because price is near a level.')],
 examDesc:'The five levels, spotting the sweep on a chart, and reading the WATCHING tab.'});
/* ---------- x03 · confirmation ---------- */
chartMod({id:'x03',o:3,ph:0,t:'Confirmation: CISD and the Inverted Gap',out:'Find the CISD line, and the candle that closes through it.',
 ls:['The delivery run','The CISD line','A close, not a wick','The inverted gap','The close-through line','When the entry tab appears'],
 task:'On a 1-minute chart in replay, find three sweeps. For each, mark the first candle of the run that pushed into the level, draw a line at its open, and find the first candle that closed through it.',
 ex:()=>exoScn(rr(903),{side:'long',fast:true,out:'target',align:'gap'}),
 learn:[
  {t:'The delivery run',h:`<p>The <b>delivery run</b> is the run of same-direction candles that pushed price into the level. ECHO X ORBIT marks it. Where it <b>started</b> is the line that matters.</p>`},
  {t:'The CISD line',h:def('<p><b>CISD (change in state of delivery):</b> a candle <b>closes back through the opening price of the delivery run</b>. That says the push has been overturned.</p>')+`<p>For a swept low (a long), the run was down, so the line is its opening price and you need a close <b>above</b> it. For a swept high (a short), you need a close <b>below</b>.</p>`},
  {t:'A close, not a wick',h:`<p>Wait for the candle to <b>close</b>. A wick through the line does nothing. This is the same close rule you used for break of structure and fair value gaps.</p>`},
  {t:'The inverted gap',h:`<p>There is a second way to confirm: an <b>iFVG</b>. A one-minute gap formed <b>inside the run</b> is closed through the wrong way by a later candle. If a CISD and an inverted gap confirm on the same candle, that is normal: it is <b>one setup</b>.</p>`},
  {t:'The close-through line',h:`<p>A <b>dotted orange line</b> on the chart shows the price a candle has to close through to confirm. Know where it is before the confirmation arrives.</p>`},
  {t:'When the entry tab appears',h:`<p>The <b>entry tab</b> appears at the <b>open of the candle after the confirmation</b>. It reads the name, the direction, the price and the checks, for example <b>ExO · SHORT 25100.00 · 3/3</b>. If no entry tab appears after a clear-looking reversal, a filter dropped it. That is by design.</p>`}],
 recall:rc('Levels and the Sweep','How long does a watch last without a confirmation?',['30 candles','3 candles','All day','Until the next hour'],'After 30 candles the watch expires.'),
 see:e=>stepsOf(e,['sweep','confirm','entry']),
 sum:e=>({ov:[exLvl(e),exCisd(e)]}),
 drills:[exCisdLine,exTapConfirm,exCount,exTapSweep],
 bank:[
  mcq('CISD','What does CISD stand for?',['Change in state of delivery','Close inside the second day','Candle inversion signal direction','Confirmed imbalance structure divergence'],'Change in state of delivery.'),
  mcq('CISD','What is the delivery run?',['The run of same-direction candles that pushed price into the level','The candle after the sweep','The target','The window'],'Its opening price is the CISD line.'),
  mcq('CISD','Where is the CISD line?',['At the opening price of the delivery run','At the swept level','At the previous day close','At the entry'],'A close back through it confirms.'),
  mcq('CISD','Does a wick through the CISD line confirm?',['No: a candle has to close through it','Yes','Only on the 1-hour','Only in Discretionary mode'],'Closes count, wicks do not.'),
  mcq('CISD','What is an iFVG in ECHO X ORBIT?',['A one-minute gap inside the run that a later candle closes through the wrong way','A 4-hour gap','A daily gap','A gap at the open'],'A second way to confirm.'),
  mcq('CISD','A CISD and an inverted gap confirm on the same candle. How many setups is that?',['One','Two','None','Three'],'It is normal, and it is one setup.'),
  mcq('CISD','Within how many candles of the sweep can a candle confirm?',['30','3','300','Any time that day'],'After 30 candles the watch expires.'),
  mcq('CISD','Where does the entry tab appear?',['At the open of the candle after the confirmation','On the sweep candle','At the swept level','At the close of the hour'],'Enter at that candle\'s open, or as close as you can.'),
  mcq('CISD','No entry tab appears after a clear-looking reversal. What happened?',['A filter dropped it, by design','The indicator is broken','You must enter by hand','The candle was too slow'],'Do not force it.'),
  mcq('CISD','For a swept low, which close confirms?',['A close above the CISD line','A close below the swept low','A close below the CISD line','A close at the level'],'The run was down, so you need a close back above its opening price.')],
 examDesc:'The delivery run, the CISD line, the confirming candle and the entry tab.'});
/* ---------- x04 · the three checks ---------- */
chartMod({id:'x04',o:4,ph:0,t:'The Three Checks',out:'Score a setup out of three and say what the score means.',
 ls:['The three checks','Reading n/3','Slow turns: the B setup','A wick-only rejection','Strict and Discretionary again'],
 task:'On a 1-minute chart in replay, find three confirmed setups. For each, write the three checks (closed back inside, reacted within 3 candles, swept the previous 1H or previous-day level) as yes or no and the n/3 score.',
 ex:()=>exoScn(rr(904),{side:'short',fast:true,out:'target',align:'gap',level:'1H'}),
 learn:[
  {t:'The three checks',h:tblx(['Check','What it says','If it is false'],[['Closed back inside the swept level','The market rejected the level with a body, not just a wick','Weakest warning. Ask whether a wick-only rejection is happening at a very obvious level; if you cannot say why it is still good, skip'],['Reacted within 3 candles','A fast V-shaped turn. Slow turns show the sweepers were not trapped','A slow confirmation (4 to 30 candles) is a B setup: smaller size or skip'],['Swept the previous 1H or previous-day level','Bigger liquidity, bigger reaction','A 15-minute-only sweep is a small setup: take it only if it lines up with a gap or rejection block']])},
  {t:'Reading n/3',h:key('<p><b>3/3</b> is the base case. <b>2/3</b> needs a reason you can write down. <b>1/3 or lower</b> is usually a skip.</p>','The rule of thumb')+`<p>The entry tab shows the score, for example <b>ExO · SHORT 25100.00 · 3/3</b>. Each check has its own show/hide switch, but Strict mode still uses all three.</p>`},
  {t:'Slow turns: the B setup',h:`<p>If price chops sideways at the level for ten or more candles before confirming, the setup is <b>slow</b>. The longer it takes, the weaker the signal. A confirmation after candle 3 fails check 2: treat it as a <b>B setup</b> and take it smaller, or skip it, especially if price has drifted sideways at the level in between.</p>`},
  {t:'A wick-only rejection',h:`<p>If the confirming candle closes through the CISD line but <b>not back inside</b> the swept level, check 1 is false and Discretionary mode shows 2/3. Decide: is the level an obvious 1-hour or previous-day one, and does it line up with a gap or rejection block? If yes, it can still be taken. If not, skip.</p>`},
  {t:'Strict and Discretionary again',h:`<p><b>Strict</b> only continues at 3/3. <b>Discretionary</b> draws every confirmed setup with its checklist, and the n/3 is your starting point for the decision. Whatever the score, write down why you took it or skipped it.</p>`}],
 recall:rc('Confirmation: CISD and the Inverted Gap','Does a wick through the CISD line confirm?',['No: a candle has to close through it','Yes','Only on the 1-hour','Only in Discretionary mode'],'Closes count, wicks do not.'),
 see:e=>stepsOf(e,['sweep','confirm','entry']),
 sum:e=>({ov:[exLvl(e),exCisd(e)]}),
 drills:[exChecks,exCount,exAlignQ,exTapConfirm],
 bank:[
  mcq('Checks','How many checks does ECHO X ORBIT score?',['Three','One','Five','Seven'],'Closed back inside, reacted within 3 candles, swept the previous 1H or previous-day level.'),
  mcq('Checks','Which is a check?',['Reacted within 3 candles','The news is quiet','Price is above the open','The window is open'],'A fast V-shaped turn.'),
  mcq('Checks','What is the base case?',['3/3','2/3','1/3','0/3'],'3/3.'),
  mcq('Checks','A setup scores 2/3. What do you do?',['You need a reason you can write down','Always take it','Always skip it','Double the size'],'2/3 needs a reason you can write down.'),
  mcq('Checks','A setup scores 1/3. What do you do?',['Usually skip','Take it at full size','Take it twice','Wait for 0/3'],'1/3 or lower is usually a skip.'),
  mcq('Checks','A confirmation arrives on candle 7 after the sweep. Which check fails?',['Reacted within 3 candles','Closed back inside','Swept the previous 1H or previous-day level','None'],'A slow turn is a B setup.'),
  mcq('Checks','A B setup is…',['A slow confirmation (4 to 30 candles): smaller size or skip','A setup on the 2-hour','A setup with a bigger stop','A setup in London'],'The longer it takes, the weaker the signal.'),
  mcq('Checks','Only a 15-minute level was swept. What do you do?',['Take it only if it lines up with a gap or rejection block','Always take it','Always skip it','Wait for a bigger target'],'A 15-minute-only sweep is a small setup.'),
  mcq('Checks','The confirming candle closes through the CISD line but not back inside the swept level. What does Discretionary mode show?',['2/3','3/3','0/3','Nothing'],'Check 1 is false.'),
  mcq('Checks','Which mode only continues at 3/3?',['Strict','Discretionary','Both','Neither'],'Strict.')],
 examDesc:'Scoring a setup, what n/3 means, and slow turns.'});
/* ---------- x05 · alignment ---------- */
chartMod({id:'x05',o:5,ph:0,t:'Alignment: Gaps and Rejection Blocks',out:'Say whether a sweep lines up with an open gap or rejection block, and grade the setup.',
 ls:['What alignment is','Right side for a short, right side for a long','Look at the 15-minute and 1-hour charts only','Grading the setup','A 4-hour block on its own','A pointer, not a promise'],
 task:'On the 15-minute and 1-hour charts, find three recent sweeps. For each, say whether the sweep extreme sat inside an unfilled gap or the wick zone of a rejection block of the right side, and grade it.',
 ex:()=>exoScn(rr(905),{side:'long',fast:true,out:'target',align:'gap'}),
 learn:[
  {t:'What alignment is',h:`<p>This is the layer that makes ECHO X ORBIT <b>discretionary</b>. A swept extreme that sits inside an <b>open gap</b> or the <b>wick zone of a rejection block</b> of the opposite side is price being delivered into an area where the other side was already waiting.</p>`},
  {t:'Right side for a short, right side for a long',h:tblx(['','Short','Long'],[['The sweep extreme sits inside…','An unfilled bearish gap, or the upper-wick zone of a bearish rejection block','An unfilled bullish gap, or the lower-wick zone of a bullish rejection block']])},
  {t:'Look at the 15-minute and 1-hour charts only',h:`<p>When a WATCHING tab appears, look <b>left</b> on the 15-minute and 1-hour charts. Is the swept extreme inside a gap or a rejection block of the right side? The entry tab also names it: <b>FVG</b>, <b>RB</b> or <b>FVG + RB</b> when the sweep extreme sat inside an open 15-minute or 1-hour zone.</p>`},
  {t:'Grading the setup',h:tblx(['Aligned with…','Grade'],[['A gap and a rejection block','The highest-quality setup: take it at your full planned risk'],['One of them','A normal setup'],['Nothing on the 15m or 1H','Skip, unless there is a very specific reason you can write down']])},
  {t:'A 4-hour block on its own',h:`<p>A <b>4-hour</b> rejection block on its own is not alignment. Treat it with caution and do not count it as one of the two kinds.</p>`},
  {t:'A pointer, not a promise',h:key('<p>The alignment mark on the chart uses the 15-minute and 1-hour gaps and large-wick candles the script keeps in memory. Treat it as a <b>pointer</b>, not a promise: check it by eye, log it, and let your own record decide how much weight it earns.</p>')}],
 recall:rc('The Three Checks','What is the base case score?',['3/3','2/3','1/3','0/3'],'3/3 is the base case.'),
 see:e=>stepsOf(e,['sweep','align','confirm']),
 sum:e=>({ov:[exLvl(e),...(exAlign(e)?[exAlign(e)]:[])]}),
 drills:[exAlignQ,exAlignQ,exChecks,exTapSweep],
 bank:[
  mcq('Alignment','For a short, the sweep extreme sits inside…',['An unfilled bearish gap or the upper-wick zone of a bearish rejection block','A bullish gap','The previous day close','A round number'],'The other side was already waiting there.'),
  mcq('Alignment','For a long, the sweep extreme sits inside…',['An unfilled bullish gap or the lower-wick zone of a bullish rejection block','A bearish gap','The weekly open','A moving average'],'The mirror image.'),
  mcq('Alignment','Which charts do you check for alignment?',['The 15-minute and 1-hour','The 4-hour only','The daily only','The 1-minute only'],'Look left on the 15m and 1H.'),
  mcq('Alignment','Aligned with a gap and a rejection block. What is the grade?',['The highest-quality setup: full planned risk','Skip','A B setup','A news setup'],'Take it at full planned risk.'),
  mcq('Alignment','Aligned with one of them. What is the grade?',['A normal setup','The best setup','Skip','Double size'],'Normal.'),
  mcq('Alignment','Aligned with nothing on the 15m or 1H. What do you do?',['Skip, unless there is a very specific reason','Take it at full size','Take it twice','Wait for the 4-hour'],'Write down the reason or skip.'),
  mcq('Alignment','A 4-hour rejection block is the only thing near the sweep. What do you do?',['Treat it with caution: it is not alignment on its own','Count it as the best alignment','Ignore the checks','Double the size'],'Do not count it as one of the two kinds.'),
  mcq('Alignment','What does the entry tab show when the sweep extreme sat inside a gap?',['FVG','TOP','RB only','Nothing'],'FVG, RB, or FVG + RB.'),
  mcq('Alignment','The alignment mark on the chart is…',['A pointer, not a promise','A guarantee','An order','A signal to enter'],'Check it by eye and log it.'),
  mcq('Alignment','Does alignment fix a bad stretch?',['No: it is a layer of judgement, not a cure','Yes, always','Only in Strict','Only on Fridays'],'Keep logging and let your own record decide.')],
 examDesc:'Alignment with gaps and rejection blocks, and grading a setup.'});
/* ---------- x06 · the trade ---------- */
chartMod({id:'x06',o:6,ph:1,t:'Entry, Stop, Target and Break-even',out:'Place the entry, stop, target and break-even step, and know how a trade ends.',
 ls:['The entry','The stop','The stop band','The target','Break-even at +0.25R','How a trade ends','What you may not change'],
 task:'On a 1-minute chart in replay, find three confirmed setups. For each, write the entry (the next candle\'s open), the stop (one point beyond the sweep extreme), the break-even price (+0.25R) and the target (half the swept range beyond its far end).',
 ex:()=>exoScn(rr(906),{side:'short',fast:true,out:'target',align:'gap',level:'1H'}),
 learn:[
  {t:'The entry',h:`<p>Enter at <b>market at the open of the candle after the confirmation</b>, or as close to it as you can. Place the stop and a limit at the target at once. If price has already run <b>more than a quarter of the stop</b> away from the entry price, <b>skip it</b>: chasing is not part of the plan.</p>`},
  {t:'The stop',h:`<p>The stop sits <b>one point beyond the sweep extreme</b>. If price makes a lower low (or a higher high) after your watch started and then confirms, the extreme is the new one and the stop moves with it.</p>`},
  {t:'The stop band',h:`<p>The stop must be between <b>0.07 and 0.16 of a typical day range</b> (about 20 to 50 points on NQ now) and never smaller than <b>4 points</b>. Otherwise the setup is dropped, by design: a tiny stop gets stopped by noise and costs, and a wide stop cuts your size.</p>`},
  {t:'The target',h:`<p>The target is <b>0.5 standard deviation beyond the swept range</b>: take the size of the range the swept level came from, project it beyond that range's far end, and use half of it. The setup is skipped if the target is <b>closer than 1.2 times the stop</b>.</p>${key('<p>Example for a short: the previous 1-hour candle that made the swept high ranged 120 points. The target is half of that, 60 points, <b>below its low</b>.</p>')}`},
  {t:'Break-even at +0.25R',h:`<p><b>R</b> is your stop distance. When price reaches <b>+0.25R</b> (a quarter of the way to your risk), the stop line turns <b>orange</b> and an alert fires: <b>move your stop to the entry</b>. If price then returns to the entry, you are out for about the cost of the trade: a <b>scratch</b>. A scratch is the plan working, and it is not a win.</p>`},
  {t:'How a trade ends',h:`<p>The trade ends at the <b>stop</b>, the <b>target</b>, or after <b>120 minutes</b>, whichever comes first. If an hour block changes while you are in a trade, the trade runs to its own exit; a new trade in the next block is allowed once it has closed. One position at a time.</p>`},
  {t:'What you may not change',h:tblx(['Never change','Why'],[['Stop placement','One point beyond the sweep extreme'],['Moving the stop to break-even at +0.25R','Skipping it because a trade "looks strong" is a classic mistake'],['Widening a stop','Giving it room turns a small loss into a big one'],['Adding to a loser or re-entering the same level in the same hour block','The setup is over'],['Holding past 120 minutes','The plan runs itself once you are in']])}],
 recall:rc('Alignment: Gaps and Rejection Blocks','Aligned with nothing on the 15m or 1H. What do you do?',['Skip, unless there is a very specific reason','Take it at full size','Take it twice','Wait for the 4-hour'],'Write down the reason or skip.'),
 see:e=>stepsOf(e,['confirm','entry','result']),
 sum:e=>({ov:[exLvl(e),...exTrade(e,e.exitI)]}),
 drills:[exStopLine,exTarget,exReplayLike,exTapConfirm],
 bank:[
  mcq('Trade','Where is the entry?',['Market at the open of the candle after the confirmation','At the swept level','At the previous close','At a retest of the line'],'No waiting for a retest.'),
  mcq('Trade','Price already ran more than a quarter of the stop from the entry price. What do you do?',['Skip it','Chase it with a wider stop','Add size','Wait for 3/3'],'Chasing is not part of the plan.'),
  mcq('Trade','Where does the stop go?',['One point beyond the sweep extreme','At the entry','Beyond the previous day high','At the target'],'The sweep extreme plus one point.'),
  mcq('Trade','A setup\'s stop would be smaller than 4 points. What happens?',['The setup is dropped','The stop is widened','The trade is taken anyway','The target is moved'],'Tiny stops get stopped by noise.'),
  mcq('Trade','What is the target?',['Half a standard deviation beyond the swept range','Always the previous day high','Always 1R','The entry plus 10 points'],'Half the size of the swept range beyond its far end.'),
  mcq('Trade','The target is closer than 1.2 times the stop. What happens?',['The setup is skipped','The stop is widened','The target is moved out','The trade is taken at half size'],'Skip if the target is closer than 1.2 times the stop.'),
  mcq('Trade','When does the stop line turn orange?',['When price reaches +0.25R','At the target','At entry','After 120 minutes'],'Move your stop to the entry.'),
  mcq('Trade','Price reached +0.25R, the stop moved to the entry, and price came back to the entry. What is it?',['A scratch','A win','A full loss','A time exit'],'About the cost of the trade. It is not a win.'),
  mcq('Trade','How long can a trade run?',['Until the stop, the target, or 120 minutes','Until the end of the day','Until the next hour block','Forever'],'Whichever comes first.'),
  mcq('Trade','A new setup in the opposite direction appears while you are in a trade. What do you do?',['Do not open it: one position at a time','Open it too','Reverse your trade','Double up'],'Log it as skipped.'),
  mcq('Trade','Which may you NOT change?',['Moving the stop to break-even at +0.25R','Which setups you take','Your dollar risk','Standing aside around news'],'The plan runs itself once you are in.')],
 examDesc:'Entry, stop, target, break-even and how a trade ends.'});
/* ---------- x07 · the scenario playbook ---------- */
quick({id:'x07',o:7,ph:1,t:'The Scenario Playbook',out:'Know what to do in each "if this, then that" situation, and which advice is tested and which is judgement.',
 ls:['Before the sweep','At the sweep','Confirmation and entry','In the trade','After the trade','Day-level situations'],
 task:'Write the playbook on one page: for each of the six situations, one "if this, then that" in your own words. Mark each one tested rule or your own judgement.',
 learn:[
  {t:'Rules and judgement',h:`<p>The rules about stops, targets, break-even and filters come from the indicator's design. The guidance about <b>news, trend days and chop days</b> is <b>judgement</b>, which is why it says "consider" or "your call". Know which is which.</p>`},
  {t:'Before the sweep',h:tblx(['If this happens','Then do this'],[['Price is drifting toward a level and you have no setup yet','Mark the level. Do nothing. Never enter because price is near the level'],['Two levels sit close together','Treat the pair as one stack'],['A level was already swept earlier in the same hour','It does not trigger again in that hour block: look for the next untouched level'],['A big news candle spikes through several levels','One watching tab, one setup. Consider standing aside for a few minutes after the release']])},
  {t:'At the sweep',h:tblx(['If this happens','Then do this'],[['WATCHING appears and the candle keeps pushing','Fine. The extreme updates. Do nothing until a candle closes through the CISD line'],['Price chops sideways for ten or more candles','A slow setup: the longer it takes, the weaker the signal'],['30 candles pass with no confirmation','The watch expires. Wait for a new sweep'],['Price makes a lower low (or a higher high) after your watch started, then confirms','The extreme is the new one and the stop moves with it. Check the stop band still fits'],['A swept high and a swept low happen close together','Follow each side separately and take only the one with better checks and alignment. Never hold longs and shorts at once']])},
  {t:'Confirmation and entry',h:tblx(['If this happens','Then do this'],[['The confirming candle closes through the CISD line but not back inside the level','Check 1 is false. Decide whether the level and alignment justify it, or skip'],['The entry tab appears but price already ran more than 0.25R','Skip it'],['No entry tab appears after a clear-looking reversal','A filter dropped it. Do not force it'],['The stop would be tiny, or over the band','The script skips it. Do not take it by hand'],['A CISD and an inverted gap confirm on the same candle','Normal. It is one setup']])},
  {t:'In the trade',h:tblx(['If this happens','Then do this'],[['Price goes straight to the target','Take it at the line. Do not move the target further out'],['Price reaches +0.25R then falls back','The stop was at the entry: a scratch. The plan working'],['Price spikes through the stop','You are out at the stop. Log it. Do not re-enter the same level in the same hour block'],['A news release hits while you are in a trade','The stop stays where it is. Do not widen it. If you want to be flat before a release, close and log it as manual'],['A new setup in the opposite direction appears','Do not open it. One position at a time']])},
  {t:'After the trade',h:tblx(['If this happens','Then do this'],[['A stop (full loss)','Log it. Check which check or alignment was missing. Stop at your own daily maximum of losses'],['A scratch','Counts as a small loss of cost. Do not count it as a win'],['A target','Log it. Do not size up the next trade because of it'],['Two losses in a row','Stop for the day if you set that rule. A rule you set before the day beats a feeling in the moment']])},
  {t:'Day-level situations',h:tblx(['If this happens','Then do this (judgement)'],[['A strong trend day','Sweeps against the trend revert less often. In Discretionary mode skip counter-trend setups unless they are 3/3 and aligned with a higher-timeframe zone'],['A narrow chop day','More setups, smaller moves. Keep the stop-band filter on'],['A wide gap open at 9:30','Previous-day levels may already be swept at the open. Look for the next level instead of forcing a trade'],['You are not seeing setups','Normal. Do not loosen rules because it is quiet'],['An hour changes mid-trade','The trade runs to its own exit. A new trade in the next block is allowed once the first has closed']])}],
 recall:rc('Entry, Stop, Target and Break-even','Price already ran more than a quarter of the stop from the entry price. What do you do?',['Skip it','Chase it with a wider stop','Add size','Wait for 3/3'],'Chasing is not part of the plan.'),
 steps:[['<b>The six situations.</b>',tblx(['Moment','Rule of thumb'],[['Before the sweep','Mark the level, do nothing'],['At the sweep','Wait for a close through the CISD line'],['Entry','Skip if price ran more than 0.25R'],['In the trade','Stop stays, no widening, one position'],['After the trade','Log it, stop at your own daily maximum'],['The day','Trend day: with the trend; chop day: keep the filters']])]],
 gens:[exChecks,exAlignQ],
 bank:BANKS('Scenario',[
  ['Price is drifting toward a level and you have no setup. What do you do?',['Mark the level and do nothing','Enter early','Place a limit at the level','Double up'],'Never enter because price is near a level.'],
  ['A level was already swept earlier in the hour block. What happens?',['It does not trigger again unless a new level is swept','It triggers again','The block is cancelled','The stop doubles'],'Look for the next untouched level.'],
  ['WATCHING appears and the candle keeps pushing. What do you do?',['Nothing: the extreme updates and you wait for a close through the CISD line','Enter now','Close the chart','Widen the stop'],'Fine. The stop moves with the extreme.'],
  ['30 candles pass with no confirmation. What happens?',['The watch expires and nothing is traded','You enter at the 30th candle','The stop doubles','The target moves'],'Wait for a new sweep.'],
  ['A swept high and a swept low happen close together. What do you do?',['Take only the side with better checks and alignment','Take both','Take neither','Hold longs and shorts at once'],'Never hold longs and shorts at once.'],
  ['The entry tab appears but price already ran more than a quarter of the stop. What do you do?',['Skip it','Chase it','Add contracts','Wait for a retest'],'Chasing is not part of the plan.'],
  ['The stop would be smaller than 4 points. What do you do?',['Nothing: the script skips it','Take it by hand','Take it at half size','Widen it to 20'],'Tiny stops get stopped by noise.'],
  ['Price goes straight to the target. What do you do?',['Take it at the line','Move the target further out','Add to the trade','Remove the stop'],'Do not move the target further out in this plan.'],
  ['A news release hits while you are in a trade. What do you do?',['Leave the stop where it is, and do not widen it','Widen the stop','Add to the trade','Remove the stop'],'If you want to be flat before a release, close the trade and log it as manual.'],
  ['You take a full stop. What do you do?',['Log it and do not re-enter the same level in the same hour block','Re-enter the same level','Double the size next time','Skip logging'],'A normal loss at the planned risk.'],
  ['You are stopped at the entry after break-even. How do you count it?',['A scratch: a small loss of cost, not a win','A win','Nothing','A full loss'],'Do not count it as a win when you judge your results.'],
  ['You hit a target. What do you do with the next trade\'s size?',['Keep it the same: do not size up because of the last result','Double it','Halve it','Skip the next trade'],'A target is not a reason to size up.'],
  ['It is a strong trend day. What does the judgement say?',['In Discretionary mode skip counter-trend setups unless they are 3/3 and aligned with a higher-timeframe zone','Take every counter-trend setup','Skip the whole day','Double the size'],'This is judgement, not a tested rule.']]),
 examDesc:'The if-this-then-that situations before, during and after a trade, and the trend and chop day guidance.'});
/* ---------- x08 · discretion, risk and the log ---------- */
quick({id:'x08',o:8,ph:1,t:'Discretion, Risk and the Log',out:'Know what you may decide and what you may not, run the daily routine, and keep the log.',
 ls:['What you may decide','What you may not change','The routine','Risk first, then size','The log','Common mistakes'],
 task:'Write your own ECHO X ORBIT rules card: your hours, how many losses you stop after, your dollar risk per trade, and what you do around news. Then copy the log columns into your journal.',
 learn:[
  {t:'What you may decide',h:tblx(['You may decide','You may not change'],[['Which setups to take or skip (2/3, B setups, news, trend day)','Stop placement (one point beyond the sweep extreme)'],['Whether alignment with a gap or rejection block is good enough','Moving the stop to break-even at +0.25R'],['Your dollar risk per trade (inside the stop band)','Widening a stop'],['Standing aside around news','Adding to a loser, or re-entering the same level in the same hour'],['Which hours you trade','Holding past 120 minutes']])+`<p>The point of discretion is <b>selection</b>. Once you are in, the plan runs itself.</p>`},
  {t:'The routine',h:`<p><b>Before the session (5 minutes):</b></p><ol><li>Open the 1-minute chart with ExO on. Note the previous-day high and low, the previous 1-hour high and low, and where the overnight range sits.</li><li>Check the calendar for 8:30 and 10:00 releases and any Fed speaker. Decide now whether you trade through them or stand aside, and write it down.</li><li>Set your day's maximum: how many losing trades you stop after (a suggestion is 2) and your dollar risk per trade.</li></ol><p><b>During the session:</b> wait; a grey WATCHING tab means do nothing yet; when the entry tab appears, enter at the next open (skip if price already ran more than a quarter of the stop); move the stop when the line turns orange; the trade ends at the stop, the target or 120 minutes.</p><p><b>After the session (5 minutes):</b> screenshot every setup, taken or skipped, and log each one.</p>`},
  {t:'Risk first, then size',h:key('<p>Pick your <b>dollar risk per trade first</b>, then size from the stop: <b>contracts = dollar risk ÷ (stop in points × point value)</b>. MNQ is $2 per point and NQ is $20 per point.</p>')+`<p>Keep the risk a small fraction of your account's loss limit, and start small on replay or simulation. Stop for the day after your own maximum number of losses, or at your daily loss limit, whichever comes first. Use limit orders where you can and watch your fills: slippage adds up. On a prop account, check your firm's rules on holding through news, consistency and daily loss before you trade this live.</p>`},
  {t:'The log',h:`<p>Log every setup, taken or skipped:</p>${tblx(['Column','What goes in it'],[['Date and time (NY)','When the setup appeared'],['Long / short','Direction'],['Level swept','Which of the five levels'],['Checks n/3','The score on the tab'],['Aligned (gap / block)','FVG, RB, both, or none'],['Taken?','Yes or no'],['Why','The reason, in a sentence'],['Result','Stop, scratch, target or time']])}<p>Once a week, count stops, scratches, targets and time exits separately. After a good number of setups, compare the ones you took with the ones you skipped. If your picks are clearly better, you have found what your eye adds. If they are not, trade Strict mode only.</p>`},
  {t:'Common mistakes',h:`<ul><li>Entering on the sweep before confirmation.</li><li>Counting scratches as wins.</li><li>Moving the stop farther away "to give it room".</li><li>Skipping the break-even move because the trade "looks strong".</li><li>Taking every setup in Discretionary mode without logging why.</li><li>Trading 2/3 and 1/3 setups at full size on a bad day to "make it back".</li><li>Trading hours outside the default window without reading them as your own call.</li><li>Ignoring fills.</li></ul>`}],
 recall:rc('The Scenario Playbook','A swept high and a swept low happen close together. What do you do?',['Take only the side with better checks and alignment','Take both','Take neither','Hold longs and shorts at once'],'Never hold longs and shorts at once.'),
 steps:[['<b>Your rules card.</b>',tblx(['Item','Write it down'],[['Hours','The blocks you trade'],['Daily maximum','How many losses you stop after'],['Dollar risk','Per trade, before sizing'],['News','Trade through or stand aside']])]],
 gens:[exChecks,exAlignQ],
 bank:BANKS('Discretion',[
  ['Which of these may you decide?',['Which setups to take or skip','Where the stop goes','Whether to move the stop to break-even','Whether to hold past 120 minutes'],'Discretion is selection.'],
  ['Which may you NOT change?',['Stop placement','Which hours you trade','Your dollar risk','Whether you stand aside around news'],'The stop goes one point beyond the sweep extreme.'],
  ['What do you set before the session?',['Your daily maximum of losses and your dollar risk per trade','The target','The stop','The entry'],'A rule set before the day beats a feeling in the moment.'],
  ['What comes first: size or risk?',['Your dollar risk, then size from the stop','Size, then risk','The target','The window'],'Contracts = dollar risk ÷ (stop points × point value).'],
  ['How should you check a prop account before trading ECHO X ORBIT live?',['Check your firm\'s rules on news, consistency and daily loss','Nothing: all firms are the same','Ask the broker only','Skip the rules'],'Prop accounts have their own rules.'],
  ['What do you log for a setup you skipped?',['The setup, the checks, the alignment and why you skipped','Nothing','Only the winners','Only the losers'],'Log every setup, taken or skipped.'],
  ['Why compare taken setups with skipped ones?',['To see what your eye adds','To prove you are right','To skip logging','To change the stop'],'If your picks are clearly better, your eye adds something; otherwise trade Strict.'],
  ['Which is a common mistake?',['Moving the stop farther away to give it room','Logging every setup','Using limit orders','Standing aside around news'],'Never widen a stop.'],
  ['What is the right way to count a scratch?',['As a small loss of cost, not a win','As a win','As nothing','As a full loss'],'Judge your results honestly.'],
  ['After two losses in a row you set a rule to stop for the day. What do you do?',['Stop for the day','Take one more to make it back','Double the size','Change the stop'],'A rule set before the day beats a feeling in the moment.']]),
 examDesc:'What you may and may not decide, the routine, risk before size, and the log.'});
/* ---------- x09 · make the call ---------- */
chartMod({id:'x09',o:9,ph:1,flag:'Final',t:'Make the Call: ECHO X ORBIT',out:'Take or skip a setup, grade it and place the trade, on fresh charts.',
 ls:['Find the sweep and the confirmation','Score the checks','Grade the alignment','Place the stop, break-even and target','Read the outcome'],
 task:'Take a past week in replay. For every sweep you can find, write the checks, the alignment, take or skip, and why. Then compare with the outcome.',
 ex:()=>exoScn(rr(909),{side:'long',fast:true,out:'scratch',align:'gap',level:'1H'}),
 learn:[
  {t:'The call, in order',h:`<ol><li><b>Level:</b> which of the five was swept, and is it a 1-hour or previous-day level?</li><li><b>Confirmation:</b> did a candle <b>close</b> through the CISD line (or invert a gap) within 30 candles, and back inside the level?</li><li><b>Checks:</b> n/3?</li><li><b>Alignment:</b> is the sweep extreme inside a 15m or 1H gap or rejection block of the right side?</li><li><b>Filters:</b> is the stop inside the band, the target at least 1.2 times the stop away, and price not already more than a quarter of the stop away from the entry?</li><li><b>Take or skip,</b> and write down why.</li></ol>`},
  {t:'Then it runs itself',h:`<p>Once you are in: stop one point beyond the sweep extreme, break-even at +0.25R, target half the swept range beyond its far end, out at 120 minutes. No widening, no adding, one position at a time.</p>`}],
 recall:rc('Discretion, Risk and the Log','Which may you NOT change?',['Stop placement','Which hours you trade','Your dollar risk','Whether you stand aside around news'],'The stop goes one point beyond the sweep extreme.'),
 see:e=>stepsOf(e,['level','sweep','confirm','align','entry','result']),
 sum:e=>({ov:[exLvl(e),exCisd(e)]}),
 drills:[exTapSweep,exTapConfirm,exCisdLine,exStopLine,exTarget,exAlignQ,exChecks,exReplayLike],
 bank:[
  mcq('Call','You see a sweep of a 15-minute low, a close through the CISD line on candle 2, and the sweep extreme is inside an unfilled bullish 15-minute gap. What is the call?',['Take it: a fast reaction aligned with a gap, with the checks scored first','Skip it: 15-minute levels never work','Enter on the sweep','Double the size'],'A small level, so the alignment is what carries it. Score it, then decide.'),
  mcq('Call','The confirmation candle closes through the CISD line on candle 9 and the sweep extreme is aligned with nothing. What is the call?',['Skip: a slow turn with no alignment','Take it at full size','Take it twice','Wait for a retest'],'Check 2 fails and there is no alignment.'),
  mcq('Call','Price has already run more than a quarter of the stop from the entry price when you see the tab. What is the call?',['Skip it','Chase it','Add contracts','Widen the stop'],'Chasing is not part of the plan.'),
  mcq('Call','The target would be closer than 1.2 times the stop. What is the call?',['Skip: the setup fails the filter','Take it and move the target out','Take it at half size','Take it and widen the stop'],'The script drops it by design.'),
  mcq('Call','The stop would be 3 points. What is the call?',['Skip: under the 4-point minimum','Take it','Take it at double size','Move the stop to 10'],'Tiny stops get stopped by noise.'),
  mcq('Call','You are in a trade and a new setup in the opposite direction appears. What is the call?',['Do not open it: one position at a time','Reverse your trade','Open it too','Close the first one'],'Log it as skipped.'),
  mcq('Call','You are stopped at the entry after the break-even move. How do you log it?',['A scratch','A win','A full loss','A time exit'],'A small loss of cost, not a win.'),
  mcq('Call','Which setup is the best of these?',['A 1-hour sweep, a fast reaction, aligned with a gap and a rejection block','A 15-minute sweep, a slow turn, aligned with nothing','A 15-minute sweep, a fast turn, aligned with nothing','A 4-hour block alone'],'3/3 and aligned with both kinds is the highest quality.')],
 exam:{bank:4,gen:[[0,2],[1,2],[2,1],[3,1],[4,1],[5,1],[6,1],[7,1]]},examDesc:'Take-or-skip calls, the checks, alignment and the trade levels on fresh charts.'});
})();
